import {createCMSRepository} from './repository.mjs';import {mountEditor} from './editor-vendor.mjs';import {cmsConfig} from '../../hub-cms/config.mjs';import {renderArticle,validateArticle} from '../../hub-cms/render.mjs';
export async function bootCMS({document=globalThis.document,repo=createCMSRepository(),request=globalThis.fetch}={}){
 const d=document,form=d.querySelector('#cms-form'),status=d.querySelector('#cms-status'),list=d.querySelector('#cms-library'),history=d.querySelector('#cms-history'),preview=d.querySelector('#cms-preview'),field=name=>form.elements.namedItem(name);let articles=[],article=null,presentation=null,editors={},busy=false;
 const node=(tag,text)=>{const n=d.createElement(tag);if(text!==undefined)n.textContent=text;return n;};const say=text=>{status.textContent=text;};
 const template=key=>request('/hub-cms/presentation/'+key+'.json',{cache:'no-cache'}).then(r=>{if(!r.ok)throw Error('Article presentation is unavailable.');return r.json();});
 function renderLibrary(){list.replaceChildren();for(const a of articles){const row=node('tr');for(const text of [a.draft.title||'Untitled draft',a.draft.category,a.published_revision_id?'PUBLISHED':'DRAFT',a.draft.slug||'Unset',a.updated_at,a.draft.published_at||'Unknown / not published'])row.append(node('td',text));const cell=node('td'),edit=node('button','Edit / history');edit.type='button';edit.addEventListener('click',()=>run(()=>select(a)));cell.append(edit);row.append(cell);list.append(row);}}
 function choices(name,options,selected){const root=d.querySelector('[data-cms-choices="'+name+'"]');root.replaceChildren();for(const [value,label] of options){const wrapper=node('label'),input=node('input');input.type='checkbox';input.name=name;input.value=value;input.checked=selected.includes(value);wrapper.append(input,d.createTextNode(' '+label));root.append(wrapper);}}
 function content(){const draft={version:1};for(const name of ['title','slug','category','intro','seo_title','meta_description'])draft[name]=field(name).value;draft.indexable=field('indexable').checked;draft.primary_intent=field('primary_intent').value||null;draft.published_at=field('published_at').value||null;draft.content_updated_at=article?.draft.content_updated_at||null;for(const name of ['related','tools','components'])draft[name]=[...form.querySelectorAll('input[name="'+name+'"]:checked')].map(n=>n.value);draft.body={version:1,slots:Object.fromEntries(Object.entries(editors).map(([key,e])=>[key,e.get()]))};return draft;}
 function previewContent(value){validateArticle(value,presentation,{knownGuides:articles.map(a=>a.guide_key)});const registry=articles.filter(a=>a.published_revision_id||a.id===article?.id).map(a=>({guide_key:a.guide_key,content:a.id===article?.id?value:(a.published_content||a.draft)}));preview.srcdoc=renderArticle(value,presentation,registry,{preview:true});preview.hidden=false;preview.setAttribute('title','Private article preview');say('Private preview only. Draft has no public URL.');}
 async function select(value){article=value;presentation=await template(value?.seed_context.template_key||'generic');for(const e of Object.values(editors))e.destroy();editors={};const c=value?.draft||{...presentation.baseline,category:'potentiometers',body:{version:1,slots:{main:{type:'doc',content:[{type:'paragraph'}]}}}};form.reset();for(const name of ['title','slug','category','intro','seo_title','meta_description'])field(name).value=c[name];field('slug').readOnly=!!value?.published_revision_id;field('indexable').checked=c.indexable;field('primary_intent').value=c.primary_intent||'';field('published_at').value=c.published_at||'';d.querySelector('#cms-updated').textContent=c.content_updated_at||'Updated date is recorded on publication.';d.querySelector('#cms-editor-title').textContent=value?'Edit: '+(c.title||'Untitled draft'):'New draft';
  choices('related',articles.filter(a=>a.id!==value?.id).map(a=>[a.guide_key,a.draft.title||a.guide_key]),c.related);choices('tools',Object.entries(cmsConfig.tools).map(([id,t])=>[id,t.title]),c.tools);choices('components',Object.entries(cmsConfig.components).map(([id,t])=>[id,t.title]),c.components);
  const root=d.querySelector('#cms-body-editors');root.replaceChildren();for(const [key,doc] of Object.entries(c.body.slots)){const section=node('section'),label=node('h3',key==='main'?'Article body':'Further reference'),host=node('div');host.className='cms-editor';section.append(label,host);root.append(section);editors[key]=mountEditor(host,doc,presentation);}
  form.hidden=false;preview.hidden=true;history.replaceChildren();d.querySelector('#cms-publish').disabled=!value;if(value)await renderHistory();
 }
 async function renderHistory(){const revisions=await repo.history(article.id);history.replaceChildren();if(!revisions.length)history.append(node('p','No published revisions yet.'));for(const revision of revisions){const p=node('p','Revision '+revision.revision_number+' · '+revision.created_at+' · '+revision.content.title+' · '+revision.state+' · '+(revision.actor?'Admin '+revision.actor:'Source migration')),inspect=node('button','Inspect / preview'),restore=node('button','Restore as new publication');inspect.type=restore.type='button';inspect.addEventListener('click',()=>{try{previewContent(revision.content);}catch(e){say(e.message);}});restore.addEventListener('click',()=>run(async()=>{const saved=await repo.save(article,revision.content,'RESTORE',revision.id);await reload(saved.id);say('Restored as a new revision. Pages updates after successful scheduled generation; historical snapshots remain immutable.');}));p.append(inspect,restore);history.append(p);}}
 async function reload(id){articles=await repo.list();renderLibrary();if(id)await select(articles.find(a=>a.id===id));}
 async function run(fn){if(busy)return;busy=true;d.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn();}catch(e){say(e.message);}finally{busy=false;d.querySelectorAll('button').forEach(b=>b.disabled=false);d.querySelector('#cms-publish').disabled=!article;}}
 d.querySelector('#cms-new').addEventListener('click',()=>run(()=>select(null)));d.querySelector('#cms-preview-button').addEventListener('click',()=>{try{previewContent(content());}catch(e){say(e.message);}});
 form.addEventListener('submit',e=>{e.preventDefault();run(async()=>{const action=e.submitter?.value==='PUBLISH'?'PUBLISH':'DRAFT',value=content();validateArticle(value,presentation,{publishing:action==='PUBLISH',knownGuides:articles.map(a=>a.guide_key)});const saved=await repo.save(article,value,action);await reload(saved.id);say(action==='PUBLISH'?'Published revision saved. Public pages update after successful scheduled generation (normally five minutes; queueing can delay it).':'Private draft saved; public content is unchanged.');});});
 await run(async()=>{for(const c of cmsConfig.categories){const option=node('option',c.title);option.value=c.id;field('category').append(option);}await reload();say('CMS library ready. Publishing changes content, not presentation.');});return {content,select,previewContent};
}
if(typeof document!=='undefined')await bootCMS();
